N, M = map(int, input().split())
p = list(map(int, input().split())) if M > 0 else []

# Correctly construct the graph string
graph = []
for i in range(1, N+1):
    if i in p:
        graph.append(str(i))
    else:
        if graph and graph[-1] != ",":
            graph.append(",")
        graph.append(str(i))

# Process the graph to read the numbers in the required order
result = []
current_group = []
for char in graph:
    if char == ",":
        result += sorted(current_group, reverse=True)
        current_group = []
    else:
        current_group.append(char)

# Add the last group if it exists
if current_group:
    result += sorted(current_group, reverse=True)

print(*result)

N, M = map(int, input().split())
p = list(map(int, input().split())) if M > 0 else []

graph = ""
for i in range(1, N+1):
    node = str(i)
    graph += node + ("v" if i in p else ",")

result = []
for subgraph in graph.split(","):
    if "v" in subgraph:
        result += sorted(subgraph.split("v"), reverse=True)
    else:
        result.append(subgraph)

print(*result)

